 const value=Object.keys(indices).length?{source:'Cboe Global Markets',source_url:'https://www.cboe.com/tradable_products/vix/vix_historical_data',received_at:Object.keys(indices).some(name=>indices[name].received_at===receivedAt)?receivedAt:cboeVolatilityCache?.value?.received_at||receivedAt,indices}:null;
